import{_ as t,a}from"./chunks/ugso_template_condition.B9X5WNrl.js";import{_ as o,o as s,c as n,a3 as r}from"./chunks/framework.BlfGB29P.js";const i="/assets/blocks-for-ha/blocks/en/ugso_template_time_window.png",l="/assets/blocks-for-ha/blocks/en/ugso_template_change.png",c="/assets/blocks-for-ha/blocks/en/ugso_entity_value.png",d="/assets/blocks-for-ha/blocks/en/ugso_entity_value_dynamic.png",p="/assets/blocks-for-ha/blocks/en/ugso_entity_snapshot.png",u="/assets/blocks-for-ha/blocks/en/ugso_automation_control.png",m="/assets/blocks-for-ha/blocks/en/ugso_app_control.png",h="/assets/blocks-for-ha/blocks/en/ugso_template_builder.png",g="/assets/blocks-for-ha/blocks/en/ugso_template_linebreak.png",b="/assets/blocks-for-ha/blocks/en/ugso_number_format.png",f="/assets/blocks-for-ha/blocks/en/ugso_template_conditional.png",A=JSON.parse('{"title":"System values and Template builder","description":"Shared entity values, app and automation controls, and readable templates.","frontmatter":{"title":"System values and Template builder","description":"Shared entity values, app and automation controls, and readable templates."},"headers":[],"relativePath":"en/projects/blocks-for-ha/system-template.md","filePath":"en/projects/blocks-for-ha/system-template.md","lastUpdated":1793113714000}'),v={name:"en/projects/blocks-for-ha/system-template.md"};function y(k,e,_,w,x,T){return s(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="system-values-and-template-builder" tabindex="-1">System values and Template builder <a class="header-anchor" href="#system-values-and-template-builder" aria-label="Permalink to &quot;System values and Template builder&quot;">​</a></h1><p>Available since <strong>0.1.62</strong>, fully translated into DE/EN/FR. System blocks provide values for Templates as well. Reuse existing text, math and variable blocks.</p><p>Since <strong>0.1.63</strong>, Template has direct value sockets in vertical rows, similar to ioBroker&#39;s Write file block. All Template blocks have no gear; inputs match their respective types.</p><h2 id="purpose-specific-templates-since-0-1-64" tabindex="-1">Purpose-specific Templates since 0.1.64 <a class="header-anchor" href="#purpose-specific-templates-since-0-1-64" aria-label="Permalink to &quot;Purpose-specific Templates since 0.1.64&quot;">​</a></h2><p>All these blocks are in <strong>Templates</strong>, without gears. <strong>Compose text</strong> produces message text. <strong>Time within period</strong> and <strong>Check value change</strong> return a Boolean and connect directly to “Only if”, “if”, “and” or “or”. <strong>Select value – if/else</strong> offers result types with matching sockets.</p><h3 id="time-within-period" tabindex="-1">Time within period <a class="header-anchor" href="#time-within-period" aria-label="Permalink to &quot;Time within period&quot;">​</a></h3><p>Enter start and end as <code>HH:MM</code> or <code>HH:MM:SS</code>. The current HA local time is checked: <strong>start inclusive</strong>, <strong>end exclusive</strong>. With 10:00 and 13:00 this matches <code>&#39;10:00:00&#39; &lt;= now().strftime(&#39;%H:%M:%S&#39;) &lt; &#39;13:00:00&#39;</code>. 22:00 to 06:00 works across midnight. Equal boundaries return false. This is a condition, not a time trigger.</p><p><img src="'+i+'" alt="Time within period"></p><h3 id="check-value-change" tabindex="-1">Check value change <a class="header-anchor" href="#check-value-change" aria-label="Permalink to &quot;Check value change&quot;">​</a></h3><p><strong>Rise above 10</strong>, <strong>fall above 20</strong> checks <code>new value - old value &gt; 10</code> or <code>&lt; -20</code>. Enter the fall threshold as a positive magnitude. Exactly +10 or −20 does not satisfy the condition.</p><p>Leave Old value and New value empty to use <code>trigger.from_state.state</code> and <code>trigger.to_state.state</code>. This suits state triggers. A missing trigger or old state returns false, as do old <code>unknown</code>, <code>unavailable</code> and <code>none</code>. Alternatively connect values such as saved variables and System entity values. Both values use <code>float(0)</code>, matching the example: nonnumeric text counts as 0. Missing new trigger values also count as 0. Check the new value separately if this is unsuitable.</p><p><img src="'+l+'" alt="Check value change"></p><h3 id="custom-jinja-code" tabindex="-1">Custom Jinja code <a class="header-anchor" href="#custom-jinja-code" aria-label="Permalink to &quot;Custom Jinja code&quot;">​</a></h3><p><strong>Jinja – custom code</strong> accepts a complete template for a value input; <strong>Jinja – custom condition</strong> accepts a complete Boolean template. Multiline <code>{% if %}</code>, <code>{% set %}</code> and <code>{% else %}</code> remain unchanged. Only a single <code>{{ ... }}</code> expression can be used as a Compose text part; attach complete statement templates directly to the destination.</p><p><img src="'+t+'" alt="Custom code"><img src="'+a+'" alt="Custom condition"></p><p>Equivalent free-code entries have been removed from <strong>Jinja (experimental)</strong> and appear once in <strong>Templates</strong>. The experimental category retains the decomposable Jinja builder. Its parts edit Jinja expressions and do not represent additional HA actions. Older project blocks and imported original code remain readable.</p><p><strong>Control app</strong> and <strong>Control automation</strong> are in <strong>System</strong>. Since 0.1.64 they use two rows like ioBroker’s Control instance: selection above, Action below. HA apps and automation entities replace ioBroker instances.</p><h2 id="system" tabindex="-1">System <a class="header-anchor" href="#system" aria-label="Permalink to &quot;System&quot;">​</a></h2><p>Gear changes update the main block immediately: adding shows a row, removing hides it and adjusts the size, even while the popup remains open.</p><table tabindex="0"><thead><tr><th>Block</th><th>Purpose</th></tr></thead><tbody><tr><td>Entity ID</td><td>Select an entity and connect its ID to another block.</td></tr><tr><td>Value of entity</td><td>Fixed HA selection: state, name, unit, attribute, last changed or last updated.</td></tr><tr><td>Value of entity ID</td><td>Connect an ID from an Entity ID, text or variable block.</td></tr><tr><td>Read once into variable</td><td>Save a snapshot, then execute the enclosed actions. This is not a trigger. The variable is also available to subsequent HA steps.</td></tr><tr><td>Control app</td><td>Start, stop or restart. Select installed apps through Supervisor or enter the slug manually.</td></tr><tr><td>Control automation</td><td>Enable, disable, toggle or run now.</td></tr></tbody></table><p><img src="'+c+'" alt="Entity value"><img src="'+d+'" alt="Dynamic entity value"><img src="'+p+'" alt="Snapshot"><img src="'+u+'" alt="Control automation"><img src="'+m+'" alt="Control app"></p><p>Select <strong>Attribute</strong> and enter its name; the appropriate row appears automatically. States are often text. Use <strong>Conversion → to number</strong> before calculations where needed. Missing attributes and timestamps yield <code>none</code>; a missing state yields HA&#39;s <code>unknown</code>. <strong>Fallback</strong> can handle these values.</p><p>The <strong>Control automation</strong> gear adds <strong>Connect entity ID</strong>, <strong>Check conditions</strong> and <strong>Stop running actions</strong>. A connected ID replaces the fixed selection. Condition checking applies to “run now”; stopping applies to “disable”. Without an explicit option, HA defaults apply: triggering skips conditions, disabling stops running actions. Enabling listens for triggers rather than immediately running actions.</p><p><strong>Control app</strong> requires Supervisor and administrator privileges. The application receives read access to Supervisor for the selection list; start/stop/restart only happen when the exported automation executes in HA. Without Supervisor, the slug remains editable, but the action is unavailable there. Export: <code>hassio.app_start</code>, <code>hassio.app_stop</code>, <code>hassio.app_restart</code> with <code>data.app</code>.</p><h2 id="build-a-template" tabindex="-1">Build a Template <a class="header-anchor" href="#build-a-template" aria-label="Permalink to &quot;Build a Template&quot;">​</a></h2><ol><li>Attach <strong>Templates → Compose text</strong> to a text input such as “Message”.</li><li>Connect ordinary <strong>Text</strong> directly to <strong>Part 1</strong>.</li><li>Connect an <strong>Entity value from System</strong> or <strong>Number format</strong> directly to <strong>Part 2</strong>.</li><li>Filling the final input automatically adds another socket. Top-to-bottom order determines output order. Empty inputs are skipped and retain their position for undo/redo.</li></ol><p>Example: text <code>Temperature: </code> → entity value <code>sensor.temperature</code> through <strong>Number format</strong> with the math number <code>1</code> for decimal places → text <code> °C</code>. Example result: <code>Temperature: 21.6 °C</code>.</p><p><img src="'+h+'" alt="Template"><img src="'+g+'" alt="New line as a value"><img src="'+b+'" alt="Number format"><img src="'+f+'" alt="Conditional output"></p><table tabindex="0"><thead><tr><th>Addition</th><th>Meaning</th></tr></thead><tbody><tr><td>Number format</td><td>0–10 decimal places, using a decimal point. Use a math number for the count. Connect a fallback directly to its optional value input; invalid numbers otherwise produce empty text.</td></tr><tr><td>Value otherwise</td><td>Fallback for <code>unknown</code>, <code>unavailable</code>, <code>none</code> and empty text. Keeps <code>0</code> and <code>false</code>.</td></tr><tr><td>New line</td><td>Starts a new line here.</td></tr><tr><td>Select value – if/else</td><td>Choose the result type: Value, Text, Number or Boolean. Connect a Boolean to “if” and matching values to “then” and “else”. Use Compose text for multiple text parts. Empty branches produce empty text for Value/Text; Number/Boolean require both branches.</td></tr></tbody></table><p>Attach formatting directly around the value it affects. Text, numbers, entity values, newlines and conditional values use value sockets; “if” accepts only Boolean blocks. Action chains cannot connect to these inputs. Jinja characters inside ordinary text remain literal text. Older Output chains automatically migrate to direct values when loaded in the editor, retaining branches and disabled parts. Old block types remain readable for project compatibility but are no longer listed in the menu.</p><p><strong>Right-click → Template preview / Jinja</strong> shows generated code and asks HA to render current values. This is a snapshot, executes no actions and requires an accessible HA connection. Without a connection, the preview is explicitly unavailable. Credentials stay on the server. Project JSON preserves blocks, connections and gear choices. YAML contains native Jinja; YAML import may restore it as a free template block. HA may interpret pure numbers or lists in template results as native values.</p><p>References: <a href="https://www.home-assistant.io/docs/automation/automation_integration_actions/" target="_blank" rel="noreferrer">HA automation actions</a>, <a href="https://www.home-assistant.io/integrations/hassio/" target="_blank" rel="noreferrer">Supervisor</a>, <a href="https://www.home-assistant.io/docs/templating/" target="_blank" rel="noreferrer">Jinja in HA</a>.</p>',32)])])}const j=o(v,[["render",y]]);export{A as __pageData,j as default};
